/* QOVALX — الكرة الأرضية الدوّارة. Three.js. بلا اعتماديات خارجية غير المكتبة نفسها. */
(function () {
  'use strict';

  var mount = document.getElementById('globe');
  if (!mount || typeof THREE === 'undefined') return;

  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var small = window.matchMedia('(max-width: 767px)').matches;

  // فحص دعم WebGL — إن لم يتوفّر نُبقي الصورة الثابتة
  try {
    var t = document.createElement('canvas');
    if (!(t.getContext('webgl2') || t.getContext('webgl'))) return;
  } catch (e) { return; }

  var LAND = "";

  // فكّ شبكة اليابسة: 360×180 بت
  var bytes = atob(LAND), MW = 360, MH = 180;
  function isLand(lon, lat) {
    var x = Math.floor((lon + 180) / 360 * MW);
    var y = Math.floor((90 - lat) / 180 * MH);
    if (x < 0 || x >= MW || y < 0 || y >= MH) return false;
    var i = y * MW + x;
    return (bytes.charCodeAt(i >> 3) >> (7 - (i & 7))) & 1;
  }

  var NAVY = 0x011230, SURFACE = 0x071C3F, GOLD = 0xD7A347, GOLD_HI = 0xF5CD7B;

  var scene = new THREE.Scene();
  var camera = new THREE.PerspectiveCamera(38, 1, 0.1, 100);
  camera.position.z = 8.4;

  var renderer = new THREE.WebGLRenderer({ alpha: true, antialias: !small });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, small ? 1.5 : 2));
  renderer.setClearColor(0x000000, 0);
  mount.appendChild(renderer.domElement);
  renderer.domElement.setAttribute('aria-hidden', 'true');

  // مجموعة تدور، وحرف Q يبقى خارجها ثابتًا
  var globe = new THREE.Group();
  scene.add(globe);

  var R = 2.35;

  // كرة داكنة تحجب النقاط الخلفية فتبدو مجسّمة
  var core = new THREE.Mesh(
    new THREE.SphereGeometry(R * 0.985, 48, 48),
    new THREE.MeshBasicMaterial({ color: 0x03152F, transparent: true, opacity: 0.98 })
  );
  globe.add(core);

  // نقاط اليابسة موزّعة بتباعد متساوٍ عبر حلزون فيبوناتشي
  var N = small ? 9000 : 24000;
  var pos = [], col = [], sz = [];
  var gold = new THREE.Color(GOLD), goldHi = new THREE.Color(GOLD_HI);
  var phi = Math.PI * (3 - Math.sqrt(5));

  for (var i = 0; i < N; i++) {
    var y = 1 - (i / (N - 1)) * 2;
    var rad = Math.sqrt(Math.max(0, 1 - y * y));
    var th = phi * i;
    var x = Math.cos(th) * rad, z = Math.sin(th) * rad;

    var lat = Math.asin(y) * 180 / Math.PI;
    var lon = Math.atan2(x, z) * 180 / Math.PI;
    if (!isLand(lon, lat)) continue;

    pos.push(x * R, y * R, z * R);
    // بعض النقاط أسطع لتوحي بالمدن
    var bright = Math.random() > 0.88;
    var c = bright ? goldHi : gold;
    var f = bright ? 1 : 0.42 + Math.random() * 0.3;
    col.push(c.r * f, c.g * f, c.b * f);
    sz.push(bright ? 1.6 : 1.0);
  }

  var g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setAttribute('aSize', new THREE.Float32BufferAttribute(sz, 1));

  var dots = new THREE.Points(g, new THREE.ShaderMaterial({
    transparent: true, depthWrite: false,
    uniforms: { uScale: { value: small ? 48 : 62 } },
    vertexShader:
      'attribute float aSize; varying vec3 vC;' +
      'uniform float uScale;' +
      'void main(){ vC = color;' +
      'vec4 mv = modelViewMatrix * vec4(position,1.0);' +
      'gl_PointSize = min(aSize * uScale / -mv.z, 3.5);' +
      'gl_Position = projectionMatrix * mv; }',
    fragmentShader:
      'varying vec3 vC;' +
      'void main(){ vec2 d = gl_PointCoord - vec2(0.5);' +
      'float a = 1.0 - smoothstep(0.22, 0.5, length(d));' +
      'if(a < 0.02) discard;' +
      'gl_FragColor = vec4(vC, a); }',
    vertexColors: true
  }));
  globe.add(dots);

  // خطوط طول وعرض خافتة
  var grid = new THREE.LineSegments(
    new THREE.EdgesGeometry(new THREE.SphereGeometry(R * 1.002, 22, 14), 1),
    new THREE.LineBasicMaterial({ color: GOLD, transparent: true, opacity: 0.055 })
  );
  globe.add(grid);

  // وهج الغلاف الجوي
  var halo = new THREE.Mesh(
    new THREE.SphereGeometry(R * 1.16, 40, 40),
    new THREE.ShaderMaterial({
      transparent: true, side: THREE.BackSide, depthWrite: false,
      blending: THREE.AdditiveBlending,
      uniforms: { uColor: { value: new THREE.Color(0x2E5FA8) } },
      vertexShader:
        'varying float vI;' +
        'void main(){ vec3 n = normalize(normalMatrix * normal);' +
        'vec3 v = normalize(normalMatrix * vec3(0.0,0.0,1.0));' +
        'vI = pow(0.62 - dot(n, v), 2.4);' +
        'gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
      fragmentShader:
        'uniform vec3 uColor; varying float vI;' +
        'void main(){ gl_FragColor = vec4(uColor, clamp(vI,0.0,1.0) * 0.30); }'
    })
  );
  scene.add(halo);

  globe.rotation.z = -0.36;   // ميل محوري طبيعي
  globe.rotation.y = -0.6;    // يبدأ عند أفريقيا وأوروبا

  // استجابة خفيفة لحركة المؤشر
  var tx = 0, ty = 0, cxr = 0, cyr = 0;
  if (!reduced && !small) {
    window.addEventListener('pointermove', function (e) {
      tx = (e.clientX / window.innerWidth - 0.5) * 0.16;
      ty = (e.clientY / window.innerHeight - 0.5) * 0.10;
    }, { passive: true });
  }

  function resize() {
    var w = mount.clientWidth, h = mount.clientHeight || w;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  }
  resize();
  window.addEventListener('resize', resize, { passive: true });

  // الإيقاف عند الخروج من الشاشة حفاظًا على الأداء والبطارية
  var visible = true;
  if ('IntersectionObserver' in window) {
    new IntersectionObserver(function (en) { visible = en[0].isIntersecting; },
      { threshold: 0.01 }).observe(mount);
  }
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) visible = false;
  });

  mount.classList.add('is-live');   // يخفي الصورة الثابتة

  function frame() {
    requestAnimationFrame(frame);
    if (!visible) return;
    if (!reduced) globe.rotation.y += 0.0009;   // دوران بطيء ومتزن
    cxr += (ty - cxr) * 0.05;
    cyr += (tx - cyr) * 0.05;
    scene.rotation.x = cxr;
    scene.rotation.y = cyr;
    renderer.render(scene, camera);
  }
  frame();
})();
